<?php

declare(strict_types=1);

namespace Shared\Infrastructure\Security;

use Symfony\Component\EventDispatcher\Attribute\AsEventListener;
use Symfony\Component\HttpKernel\Event\RequestEvent;
use Symfony\Component\HttpKernel\Event\ResponseEvent;
use Symfony\Component\HttpKernel\KernelEvents;
use Symfony\Component\Uid\Uuid;
use Symfony\Contracts\Service\ResetInterface;

/**
 * Request id, always generated by the server (an incoming X-Request-Id is ignored) and returned in X-Request-Id.
 * A CLI process gets one per run. Reset between requests (worker mode).
 */
final class RequestIdHolder implements ResetInterface
{
    private ?string $id = null;

    #[AsEventListener(event: KernelEvents::REQUEST, priority: 4096)]
    public function onRequest(RequestEvent $event): void
    {
        if ($event->isMainRequest()) {
            $this->id = Uuid::v7()->toRfc4122();
        }
    }

    #[AsEventListener(event: KernelEvents::RESPONSE)]
    public function onResponse(ResponseEvent $event): void
    {
        if ($event->isMainRequest()) {
            $event->getResponse()->headers->set('X-Request-Id', $this->current());
        }
    }

    public function current(): string
    {
        return $this->id ??= Uuid::v7()->toRfc4122();
    }

    public function reset(): void
    {
        $this->id = null;
    }
}
